const notes=[["First impression","A vague introduction.","The service and location get lost among competing messages.","Clarity from the first glance.","Service, location and one next step help homeowners recognize the right fit."],["Services","Everything competes.","A dense list makes different services difficult to compare.","A place for every project.","Distinct service groups help homeowners find what they need."],["The work","The work deserves more room.","Repeated thumbnails give little context or detail.","Details worth a closer look.","Larger images and specific captions make the work easier to explore."],["Next step","An unclear invitation.","Urgent messages compete without explaining what happens next.","A simple way to begin.","One invitation explains what to share to start a conversation."]]
let mode='before',active=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)'),chapters=[...document.querySelectorAll('.chapter')];
function render(){const n=notes[active];document.querySelector('#note-index').textContent='0'+(active+1)+' / '+n[0].toUpperCase();document.querySelector('#note-title').textContent=n[mode==='before'?1:3];document.querySelector('#note-body').textContent=n[mode==='before'?2:4];document.querySelector('#progress').style.width=(active+1)*25+'%';document.querySelectorAll('[data-chapter]').forEach((a,i)=>{if(i===active)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');});chapters.forEach((c,i)=>{c.querySelector('.mobile-note h3').textContent=notes[i][mode==='before'?1:3];c.querySelector('.mobile-note p').textContent=notes[i][mode==='before'?2:4];});const toast=document.querySelector('#toast');if(mode==='after'&&innerWidth<=800){toast.querySelector('span:last-child').textContent=n[4];toast.hidden=false;toast.classList.remove('toast-in');requestAnimationFrame(()=>toast.classList.add('toast-in'));clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.hidden=true,4200);}else toast.hidden=true;}
function setMode(next){if(mode===next)return;const c=chapters[active],top=c.getBoundingClientRect().top;mode=next;document.body.dataset.mode=mode;document.querySelectorAll('.before').forEach(e=>e.hidden=mode!=='before');document.querySelectorAll('.after').forEach(e=>e.hidden=mode!=='after');document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));document.querySelector('#transform').replaceChildren(document.createTextNode(mode==='before'?'Transform this site ':'View the original '),window.studioIcon(mode==='before'?'sparkles':'rotate-ccw')); document.querySelector('#state-label').textContent=mode==='before'?'THE CURRENT EXPERIENCE / 4 OPPORTUNITIES':'THE NEW EXPERIENCE / 4 CONSIDERED IMPROVEMENTS';document.querySelector('#browser-mode').textContent=mode==='before'?'CURRENT':'REDESIGN';render();window.scrollBy({top:c.getBoundingClientRect().top-top,behavior:'instant'});if(!reduced.matches)document.querySelector('.canvas').animate([{opacity:.3,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'ease-out'});}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelector('#transform').onclick=()=>setMode(mode==='before'?'after':'before');
let pending=false;function update(){pending=false;let i=0;chapters.forEach((c,j)=>{if(c.getBoundingClientRect().top<innerHeight*.42)i=j;});if(i!==active){active=i;render();}}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(update);}},{passive:true});document.querySelector('#restart').onclick=()=>document.querySelector('#review').scrollIntoView({behavior:reduced.matches?'instant':'smooth'});document.querySelector('#sample-contact').onclick=()=>{document.querySelector('#sample-message').hidden=false;};render();update();
